//! # Contracts-Macros Recipe Generated Marker
//!
//! Verify generated files have an explicit "DO NOT EDIT" marker
//! header. Returns offenders missing the marker.
//!
//! Demonstrates the **CMM.135** recipe for PMAT-202 (post-milestone).
//!
//! Contract: contracts/recipe-iiur-v1.yaml
//! Citation: protoc-generated `// DO NOT EDIT` convention; rust-bindgen
//!  generated-file marker.
//!
//! Run with: cargo run --example contracts_macros_recipe_generated_marker
//!
//! Added by PMAT-202 (catalog 1441→).

use apr_cookbook::recipe::RecipeContext;
use apr_cookbook::Result;

#[derive(Debug, PartialEq)]
pub enum MarkerVerdict {
    Ok {
        missing_marker: Vec<String>,
        ok_count: u32,
    },
    InvalidConfig,
}

pub fn audit(files: &[(&str, &str)]) -> MarkerVerdict {
    if files.is_empty() {
        return MarkerVerdict::InvalidConfig;
    }
    let mut missing: Vec<String> = Vec::new();
    let mut ok_count = 0u32;
    for (name, content) in files {
        let lower = content.to_lowercase();
        if lower.contains("do not edit")
            || lower.contains("auto-generated")
            || lower.contains("autogenerated")
        {
            ok_count += 1;
        } else {
            missing.push((*name).to_string());
        }
    }
    missing.sort();
    missing.dedup();
    MarkerVerdict::Ok {
        missing_marker: missing,
        ok_count,
    }
}

fn main() -> Result<()> {
    let _ctx = RecipeContext::new("contracts_macros_recipe_generated_marker")?;

    let files = [
        ("good.rs", "// DO NOT EDIT - generated by foo\nuse std;"),
        ("bad.rs", "use std;"),
        ("auto.rs", "// auto-generated by bindgen\n"),
    ];
    println!("audit: {:?}", audit(&files));
    println!("invalid: {:?}", audit(&[]));
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn auditor_runs() {
        main().expect("recipe execution failed");
    }

    #[test]
    fn marker_present_no_offender() {
        let files = [("a.rs", "// DO NOT EDIT")];
        let v = audit(&files);
        if let MarkerVerdict::Ok { missing_marker, .. } = v {
            assert!(missing_marker.is_empty());
        }
    }

    #[test]
    fn missing_marker_flagged() {
        let files = [("a.rs", "use std;")];
        let v = audit(&files);
        if let MarkerVerdict::Ok { missing_marker, .. } = v {
            assert_eq!(missing_marker, vec!["a.rs".to_string()]);
        }
    }

    #[test]
    fn case_insensitive_match() {
        let files = [("a.rs", "// do not edit")];
        let v = audit(&files);
        if let MarkerVerdict::Ok { missing_marker, .. } = v {
            assert!(missing_marker.is_empty());
        }
    }

    #[test]
    fn empty_input_rejected() {
        assert_eq!(audit(&[]), MarkerVerdict::InvalidConfig);
    }

    #[test]
    fn auto_generated_marker_works() {
        let files = [("a.rs", "// auto-generated by tool")];
        let v = audit(&files);
        if let MarkerVerdict::Ok { missing_marker, .. } = v {
            assert!(missing_marker.is_empty());
        }
    }

    #[test]
    fn autogenerated_marker_works() {
        let files = [("a.rs", "// autogenerated\nuse std;")];
        let v = audit(&files);
        if let MarkerVerdict::Ok { missing_marker, .. } = v {
            assert!(missing_marker.is_empty());
        }
    }

    #[test]
    fn ok_count_correct() {
        let files = [("a.rs", "// DO NOT EDIT"), ("b.rs", "use std;")];
        let v = audit(&files);
        if let MarkerVerdict::Ok { ok_count, .. } = v {
            assert_eq!(ok_count, 1);
        }
    }

    #[test]
    fn offending_sorted() {
        let files = [("zeta.rs", ""), ("alpha.rs", "")];
        let v = audit(&files);
        if let MarkerVerdict::Ok { missing_marker, .. } = v {
            assert_eq!(
                missing_marker,
                vec!["alpha.rs".to_string(), "zeta.rs".to_string()]
            );
        }
    }

    #[test]
    fn deterministic() {
        let files = [("a.rs", "// DO NOT EDIT")];
        let r1 = audit(&files);
        let r2 = audit(&files);
        assert_eq!(r1, r2);
    }

    #[test]
    fn empty_content_flagged() {
        let files = [("a.rs", "")];
        let v = audit(&files);
        if let MarkerVerdict::Ok { missing_marker, .. } = v {
            assert_eq!(missing_marker, vec!["a.rs".to_string()]);
        }
    }

    #[test]
    fn many_files_handled() {
        let files: Vec<(&str, &str)> = (0..30).map(|_| ("f", "// DO NOT EDIT")).collect();
        let v = audit(&files);
        if let MarkerVerdict::Ok { ok_count, .. } = v {
            assert_eq!(ok_count, 30);
        }
    }
}
